from pathlib import Path
import base64,json
from PIL import Image,ImageDraw
R=Path(__file__).resolve().parents[2];O=R/'renders/references_fideles_v1';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
DATA={}
board=Image.new('RGB',(1400,1120),'#252832');d=ImageDraw.Draw(board)
for i,e in enumerate(m['scenes']):
 p=O/e['id'];DATA[e['id']]={**e,'images':[uri(p/l['file']) for l in e['layers']],'reference':uri(p/'REFERENCE_RECOMPOSEE.png'),'frames':[uri(p/f) for f in e['animation']['files']] if e['animation'] else [],'optional':uri(p/'OPTION_reflet_discret.png') if e['optional_subtle_variant'] else None}
 im=Image.open(p/'REFERENCE_RECOMPOSEE.png').convert('RGBA');im.thumbnail((340,242),Image.Resampling.NEAREST);x=i%4*350;y=i//4*280;board.paste(im,(x,y+27),im);d.text((x+6,y+6),e['title'],fill='white')
board.save(O/'PLANCHE_REFERENCES.png')
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PMD · références fidèles en calques</title><style>*{box-sizing:border-box}body{margin:0;background:#18212a;color:#edf1e8;font:16px system-ui}header,main,footer{padding:22px;max-width:1360px;margin:auto}.tag{color:#a3cebe;font-size:12px;letter-spacing:2px}h1{font-size:28px;margin:8px 0}p{line-height:1.55;color:#bacbd0}.bar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}button,select{background:#2e424a;color:#fff;border:1px solid #608a87;padding:10px;border-radius:6px}.grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:24px}canvas{width:100%;max-height:76vh;object-fit:contain;object-position:top;image-rendering:pixelated;background:repeating-conic-gradient(#30363d 0% 25%,#262e36 0% 50%) 50%/16px 16px}aside{background:#26353e;padding:18px;border-radius:7px}label{display:block;margin:12px 0;font-size:14px}small{color:#b9c7cc}a{color:#a6ebcf}footer{border-top:1px solid #4a656a}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style><header><div class="tag">DERNIÈRES RÉFÉRENCES / COMMIT8eb46bc</div><h1>Le layout de référence, sans réinvention</h1><p>Mêmes dimensions, silhouettes, passages et pixels. Quatorze zones et le fond nocturne fourni, séparés en calques. Six retouches de lumière très légères sont optionnelles et désactivées par défaut.</p></header><main><div class="bar"><select id="scene"></select><button id="all">Tous les calques</button><button id="none">Tout masquer</button><button id="reference">Voir la référence seule</button><button id="play">Pause animation native</button><button id="step">+1 phase</button><button id="export">Exporter la vue PNG</button></div><div class="grid"><section><canvas id="view"></canvas><p id="status"></p></section><aside><b>Calques visibles</b><div id="layers"></div><label><input type="checkbox" id="subtle">Micro-variation de lumière</label><p id="info"></p><small>Ces calques séparent les surfaces visibles et les profondeurs. Les surfaces cachées derrière les rochers/arbres ne sont pas reconstruites : ce ne sont pas des objets complets déplaçables librement.</small></aside></div></main><footer><p>Sans la micro-variation, tous les calques recomposent exactement les pixels de la référence. Les GIF à6,12 et30 phases gardent leurs frames et durées d’origine. Le fond nocturne PNG reste statique.</p><small>Les nouveaux layouts générés précédemment sont mis de côté et ne sont pas utilisés ici. Fichiers PNG et documents OpenRaster fournis. Pas de test PMDO, collision ou carte native supplémentaire.</small></footer><script>const DATA=__DATA__,sel=document.getElementById('scene'),c=document.getElementById('view'),ctx=c.getContext('2d');let e,imgs=[],anim=[],ref,option,on=[],showRef=false,playing=true,tick=0,fi=0,last=0,checks=[];function im(src){const i=new Image();i.src=src;return i}for(const [id,v]of Object.entries(DATA)){const o=document.createElement('option');o.value=id;o.textContent=v.title;sel.append(o)}sel.value='ref_01';function setup(){e=DATA[sel.value];imgs=e.images.map(im);anim=e.frames.map(im);ref=im(e.reference);option=e.optional?im(e.optional):null;on=imgs.map(()=>true);showRef=false;tick=0;fi=0;checks=[];document.getElementById('subtle').checked=false;document.getElementById('subtle').disabled=!option;const list=document.getElementById('layers');list.innerHTML='';e.layers.forEach((l,j)=>{const row=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>{on[j]=ch.checked;showRef=false};checks.push(ch);a.href=e.images[j];a.download=l.file;a.textContent=' ↓';row.append(ch,document.createTextNode(l.name.replace(/^\d+_/,'').replaceAll('_',' ')),a);list.append(row)});if(anim.length){const row=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.id='animOn';row.append(ch,document.createTextNode(' Animation native · '+anim.length+' phases'));list.append(row)}document.getElementById('info').textContent=e.size.join('×')+' · '+e.layers.length+' calques fixes'+(anim.length?' + animation native':' · statique');c.width=e.size[0];c.height=e.size[1]}sel.onchange=setup;document.getElementById('all').onclick=()=>{showRef=false;on.fill(true);checks.forEach(ch=>ch.checked=true);if(anim.length)document.getElementById('animOn').checked=true};document.getElementById('none').onclick=()=>{showRef=false;on.fill(false);checks.forEach(ch=>ch.checked=false);if(anim.length)document.getElementById('animOn').checked=false};document.getElementById('reference').onclick=()=>showRef=!showRef;document.getElementById('play').onclick=x=>{playing=!playing;x.target.textContent=playing?'Pause animation native':'Lecture animation native'};document.getElementById('step').onclick=()=>{playing=false;if(anim.length){fi=(fi+1)%anim.length;tick=e.animation.durations_ms.slice(0,fi).reduce((a,b)=>a+b,0)}document.getElementById('play').textContent='Lecture animation native'};document.getElementById('export').onclick=()=>{const a=document.createElement('a');a.href=c.toDataURL();a.download=e.id+'_vue.png';a.click()};function draw(i){if(i&&i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}function render(now){if(last&&playing)tick+=Math.min(now-last,200);last=now;ctx.clearRect(0,0,c.width,c.height);if(showRef)draw(ref);else{imgs.forEach((i,j)=>{if(on[j])draw(i)});if(anim.length){const ds=e.animation.durations_ms,total=ds.reduce((a,b)=>a+b,0);let pos=tick%total;fi=0;while(fi<ds.length-1&&pos>=ds[fi])pos-=ds[fi++];if(document.getElementById('animOn').checked)draw(anim[fi])}if(option&&document.getElementById('subtle').checked)draw(option)}document.getElementById('status').textContent=showRef?'Référence fournie · phase0':e.title+' · '+(anim.length?'phase '+fi:'statique')+' · aucun déplacement du décor';requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R/'apercu_references_fideles_v1.html').write_text(h.replace('__DATA__',json.dumps(DATA)),encoding='utf8')
